	suite.Run(t, new(workerDeploymentClientTestSuite))
}

func (d *workerDeploymentClientTestSuite) SetupTest() {
	d.mockCtrl = gomock.NewController(d.T())
	d.service = workflowservicemock.NewMockWorkflowServiceClient(d.mockCtrl)
