// fakeClient implements just the client.Client methods Client uses. Embedding
// the interface satisfies the rest; calling an unimplemented method panics,
// which is fine because the tests never exercise them.
type fakeClient struct {
	client.Client

	mu        sync.Mutex
	signals   []PublishInput
	signalErr error // when set, SignalWorkflow returns this error
}

func (f *fakeClient) SignalWorkflow(_ context.Context, _, _, signalName string, arg any) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.signalErr != nil {
		return f.signalErr
	}
	if signalName == PublishSignalName {
		f.signals = append(f.signals, arg.(PublishInput))
	}
	return nil
}

func (f *fakeClient) recorded() []PublishInput {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]PublishInput(nil), f.signals...)
}

func decodeFirstItem(t *testing.T, in PublishInput, idx int) string {
	t.Helper()
	payload, err := decodePayloadWire(in.Items[idx].Data)
	require.NoError(t, err)
	var s string
	require.NoError(t, converter.GetDefaultDataConverter().FromPayload(payload, &s))
	return s
}

func TestFlushSendsBufferedItems(t *testing.T) {
	fc := &fakeClient{}
	c := NewClient(fc, "wf-1", Options{})
	c.Topic("events").Publish("a", false)
	c.Topic("events").Publish("b", false)

	require.NoError(t, c.Flush(context.Background()))

	sigs := fc.recorded()
	require.Len(t, sigs, 1)
	require.Len(t, sigs[0].Items, 2)
	require.EqualValues(t, 1, sigs[0].Sequence)
	require.NotEmpty(t, sigs[0].PublisherID)
	require.Equal(t, "a", decodeFirstItem(t, sigs[0], 0))
	require.Equal(t, "b", decodeFirstItem(t, sigs[0], 1))

	require.NoError(t, c.Close(context.Background()))
}

// TestPayloadConvertersDriveItemConversion proves that the configured
// PayloadConverters (not the default set) serialize each item. With only the
// byte-slice converter, a []byte round-trips but a string has no converter and
// fails — whereas the default set's JSON fallback would have accepted it.
func TestPayloadConvertersDriveItemConversion(t *testing.T) {
	fc := &fakeClient{}
	c := NewClient(fc, "wf-1", Options{
		PayloadConverters: []converter.PayloadConverter{converter.NewByteSlicePayloadConverter()},
	})

	c.Topic("events").Publish([]byte("hi"), false)
	require.NoError(t, c.Flush(context.Background()))
	sigs := fc.recorded()
	require.Len(t, sigs, 1)
	payload, err := decodePayloadWire(sigs[0].Items[0].Data)
	require.NoError(t, err)
	require.Equal(t, "binary/plain", string(payload.Metadata[converter.MetadataEncoding]),
		"item must be serialized by the configured byte-slice converter")
	require.NoError(t, c.Close(context.Background()))

	// A string is unconvertible under the byte-slice-only set, so the flush
	// fails — the default set's JSON fallback would have accepted it. Use a
	// fresh client since the unconvertible item stays buffered after the error.
	c2 := NewClient(&fakeClient{}, "wf-1", Options{
		PayloadConverters: []converter.PayloadConverter{converter.NewByteSlicePayloadConverter()},
	})
	c2.Topic("events").Publish("not-bytes", false)
	require.Error(t, c2.Flush(context.Background()))
}

func TestFlushNoopWhenEmpty(t *testing.T) {
	fc := &fakeClient{}
	c := NewClient(fc, "wf-1", Options{})
	require.NoError(t, c.Flush(context.Background()))
	require.Empty(t, fc.recorded())
}

func TestSequenceAdvancesAcrossFlushes(t *testing.T) {
	fc := &fakeClient{}
	c := NewClient(fc, "wf-1", Options{})

	c.Topic("t").Publish("x", false)
	require.NoError(t, c.Flush(context.Background()))
	c.Topic("t").Publish("y", false)
	require.NoError(t, c.Flush(context.Background()))

	sigs := fc.recorded()
	require.Len(t, sigs, 2)
	require.EqualValues(t, 1, sigs[0].Sequence)
	require.EqualValues(t, 2, sigs[1].Sequence)
	require.Equal(t, sigs[0].PublisherID, sigs[1].PublisherID)

	require.NoError(t, c.Close(context.Background()))
}

func TestMaxBatchSizeTriggersFlush(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		fc := &fakeClient{}
		// Long interval so only the size threshold can trigger a flush.
		c := NewClient(fc, "wf-1", Options{BatchInterval: time.Hour, MaxBatchSize: 2})

		c.Topic("t").Publish("a", false)
		c.Topic("t").Publish("b", false) // reaches MaxBatchSize → flush

		synctest.Wait()
		require.Len(t, fc.recorded(), 1)

		require.NoError(t, c.Close(context.Background()))
	})
}

func TestCloseDrainsBuffer(t *testing.T) {
	fc := &fakeClient{}
	c := NewClient(fc, "wf-1", Options{BatchInterval: time.Hour})

	c.Topic("t").Publish("a", false)
	require.NoError(t, c.Close(context.Background()))

	sigs := fc.recorded()
	require.Len(t, sigs, 1)
	require.Len(t, sigs[0].Items, 1)
}

func TestForceFlush(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		fc := &fakeClient{}
		c := NewClient(fc, "wf-1", Options{BatchInterval: time.Hour})

		c.Topic("t").Publish("a", true) // forceFlush

		synctest.Wait()
		require.Len(t, fc.recorded(), 1)

		require.NoError(t, c.Close(context.Background()))
	})
}

func TestFlushTimeoutAfterMaxRetryDuration(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		const retryWindow = time.Millisecond
		fc := &fakeClient{signalErr: errors.New("boom")}
		c := NewClient(fc, "wf-1", Options{BatchInterval: time.Hour, MaxRetryDuration: retryWindow})

		c.Topic("t").Publish("a", false)

		// The first flush sets pending and fails to send (transient "boom").
		require.Error(t, c.Flush(context.Background()))

		time.Sleep(retryWindow + time.Nanosecond)

		var fte *FlushTimeoutError
		require.ErrorAs(t, c.Flush(context.Background()), &fte)

		require.NoError(t, c.Close(context.Background()))
	})
}

package temporal

// This file somewhat mirrors the internal SearchAttributes implementation. The purpose of this is to
// test SearchAttributes.Copy()'s map iteration being ignored with `//workflowcheck:ignore`

type (
	SearchAttributeKey interface{}

	// SearchAttributes represents a collection of typed search attributes
	SearchAttributes struct {
		untypedValue map[SearchAttributeKey]interface{}
	}

	// SearchAttributeUpdate represents a change to SearchAttributes
	SearchAttributeUpdate func(*SearchAttributes)
)

// GetUntypedValues gets a copy of the collection with raw types.
func (sa SearchAttributes) GetUntypedValues() map[SearchAttributeKey]interface{} {
	untypedValueCopy := make(map[SearchAttributeKey]interface{}, len(sa.untypedValue))
	for key, value := range sa.untypedValue {
		// Filter out nil values
		if value == nil {
			continue
		}
		switch v := value.(type) {
		case []string:
			untypedValueCopy[key] = append([]string(nil), v...)
		default:
			untypedValueCopy[key] = v
		}
	}
	return untypedValueCopy
}

// Copy creates an update that copies existing values.
//
//workflowcheck:ignore
func (sa SearchAttributes) Copy() SearchAttributeUpdate {
	return func(s *SearchAttributes) {
		// GetUntypedValues returns a copy of the map without nil values
		// so the copy won't delete any existing values
		untypedValues := sa.GetUntypedValues()
		for key, value := range untypedValues {
			s.untypedValue[key] = value
		}
	}
}

